            if char.isalpha():
                shift = 3  # Encryption shift is +3, so decrypt by -3
                start = ord('A') if char.isupper() else ord('a')
                decrypted_char = chr((ord(char) - shift - start) % 26 + start)
                decrypted += decrypted_char
            else:
                decrypted += char
        return decrypted

    def analyze_problem(self, decrypted_content):
        """Analyze the decrypted content to determine the problem type."""
        if '+' in decrypted_content:
            return "addition"
        elif '*' in decrypted_content:
            return "multiplication"
        else:
            return "unknown"

    def generate_plan(self, problem_type):
        """Generate a plan to solve the problem based on its type."""
        if problem_type == "addition":
            return ["Add the two numbers"]
        elif problem_type == "multiplication":
            return ["Multiply the two numbers"]
        else:
            return ["Not sure how to proceed"]

    def solve_problem(self, decrypted_content):
        """Solve the decrypted problem based on the identified operation."""
        if '+' in decrypted_content:
            num1, num2 = map(int, decrypted_content.split('+'))
            return num1 + num2

